// Service interface
public interface IReportService
{
    Task<string> GenerateReportAsync(CancellationToken cancellationToken = default);
}

// Simple implementation of IReportService
public class ReportService : IReportService
{
    private readonly ILogger<ReportService> _logger;

    public ReportService(ILogger<ReportService> logger)
    {
        _logger = logger;
    }

    public async Task<string> GenerateReportAsync(CancellationToken cancellationToken = default)
    {
        // Simulate some work
        await Task.Delay(TimeSpan.FromSeconds(1), cancellationToken);
        var result = $"Report generated at {DateTimeOffset.UtcNow:u}";
        _logger.LogInformation("ReportService: {Result}", result);
        return result;
    }
}

// Background service that runs every 30 seconds
public sealed class ReportBackgroundService : BackgroundService
{
    private readonly IServiceScopeFactory _scopeFactory;
    private readonly ILogger<ReportBackgroundService> _logger;
    private static readonly TimeSpan _interval = TimeSpan.FromSeconds(30);

    public ReportBackgroundService(IServiceScopeFactory scopeFactory, ILogger<ReportBackgroundService> logger)
    {
        _scopeFactory = scopeFactory;
        _logger = logger;
    }

    protected override async Task ExecuteAsync(CancellationToken stoppingToken)
    {
        while (!stoppingToken.IsCancellationRequested)
        {
            using var scope = _scopeFactory.CreateScope();
            var reportService = scope.ServiceProvider.GetRequiredService<IReportService>();

            try
            {
                var result = await reportService.GenerateReportAsync(stoppingToken);
                _logger.LogInformation("Report generated: {Result}", result);
            }
            catch (Exception ex)
            {
                _logger.LogError(ex, "Error generating report.");
            }

            try
            {
                await Task.Delay(_interval, stoppingToken);
            }
            catch (TaskCanceledException)
            {
                // Swallow cancellation during delay
            }
        }
    }
}

